<?php
require_once __DIR__ . '/includes/bootstrap.php'; require_once __DIR__ . '/services/MatchingService.php'; require_login();
$errors = [];
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf(); $reportType = post_string('report_type', 10); $itemName = post_string('item_name', 120); $category = post_string('category', 60); $colour = post_string('colour', 60); $location = post_string('location', 120); $date = post_string('incident_date', 10); $description = post_string('description', 2000);
    if (!in_array($reportType, allowed_report_types(), true) || $itemName === '' || !in_array($category, allowed_categories(), true) || !in_array($location, allowed_locations(), true) || $description === '') $errors[] = 'Complete all required fields using the available options.';
    $dateObject = DateTime::createFromFormat('Y-m-d', $date); if (!$dateObject || $dateObject->format('Y-m-d') !== $date) $errors[] = 'Enter a valid incident date.';
    if (!$errors) { $pdo = database(); $stmt = $pdo->prepare('INSERT INTO item_reports (user_id, report_type, item_name, category, colour, description, location, incident_date) VALUES (?, ?, ?, ?, ?, ?, ?, ?)'); $stmt->execute([current_user()['id'], $reportType, $itemName, $category, $colour ?: null, $description, $location, $date]); refresh_matches($pdo, (int) $pdo->lastInsertId()); flash('success', 'Your report has been published.'); redirect('my-reports.php'); }
}
$pageTitle = 'Report an item'; require __DIR__ . '/includes/header.php';
?>
<main class="page-shell"><div class="container"><div class="form-card card"><p class="eyebrow">Your report</p><h1>Report an item</h1><p class="lead">Share useful public details while keeping private proof for recovery.</p><?php foreach ($errors as $error): ?><div class="alert error"><?= e($error) ?></div><?php endforeach; ?><form method="post" class="stack"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="form-grid"><fieldset class="form-field full"><legend>Report type</legend><div class="radio-row"><label class="radio-option"><input type="radio" name="report_type" value="lost" required> I lost an item</label><label class="radio-option"><input type="radio" name="report_type" value="found"> I found an item</label></div></fieldset><div class="form-field"><label for="item_name">Item name</label><input id="item_name" name="item_name" maxlength="120" required></div><div class="form-field"><label for="category">Category</label><select id="category" name="category" required><option value="">Choose</option><?php foreach (allowed_categories() as $option): ?><option><?= e($option) ?></option><?php endforeach; ?></select></div><div class="form-field"><label for="colour">Colour</label><input id="colour" name="colour" maxlength="60"></div><div class="form-field"><label for="location">Location</label><select id="location" name="location" required><option value="">Choose</option><?php foreach (allowed_locations() as $option): ?><option><?= e($option) ?></option><?php endforeach; ?></select></div><div class="form-field"><label for="incident_date">Date lost/found</label><input id="incident_date" name="incident_date" type="date" required></div><div class="form-field full"><label for="description">Public description</label><textarea id="description" name="description" maxlength="2000" required></textarea><span class="form-note">Do not include passwords, PINs, or sensitive account details.</span></div></div><button class="button" type="submit">Submit report</button></form></div></div></main>
